import json, os

workspace = "/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-6/play/users/u045/system/state/workspace"
json_file = f"{workspace}/programs/task-8625f9bc.json"

with open(json_file, 'r') as f:
    pairs = json.load(f)

# Define the transform function
def transform(grid):
    from collections import Counter
    c = Counter(x for r in grid for x in r)
    bg = c.most_common(1)[0][0]
    pts = [(i, j) for i, r in enumerate(grid) for j, x in enumerate(r) if x != bg]
    rs = [p[0] for p in pts]; cs = [p[1] for p in pts]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    o = [row[:] for row in grid]
    # fill bounding-box border with 2 where background
    for j in range(c0, c1 + 1):
        for i in (r0, r1):
            if o[i][j] == bg: o[i][j] = 2
    for i in range(r0, r1 + 1):
        for j in (c0, c1):
            if o[i][j] == bg: o[i][j] = 2
    # complete broken interior straight lines of marks
    for j in range(c0 + 1, c1):
        col = [i for i in range(r0 + 1, r1) if grid[i][j] != bg]
        for a, b in zip(col, col[1:]):
            for i in range(a + 1, b):
                if o[i][j] == bg: o[i][j] = 2
    for i in range(r0 + 1, r1):
        row = [j for j in range(c0 + 1, c1) if grid[i] != bg]
        for a, b in zip(row, row[1:]):
            for j in range(a + 1, b):
                if o[i][j] == bg: o[i][j] = 2
    return o

# Test on all pairs
all_match = True
for idx, pair in enumerate(pairs):
    inp = pair['input']
    out = pair['output']
    result = transform(inp)
    match = result == out
    if not match:
        print(f"Pair {idx} MISMATCH!")
        all_match = False
    else:
        print(f"Pair {idx}: OK")

if all_match:
    print("ALL PAIRS MATCH!")
else:
    print("Some pairs don't match")
